files.nginx/listings.conf:
server {
    listen 8090;
    location /published/ {
        alias /srv/published/;
        autoindex on;
        autoindex_format html;
    }
    location /incoming/ {
        alias /srv/incoming/;
        autoindex on;
        autoindex_format html;
    }
}

